export {
  NumberField,
  NumberFieldScrubArea,
  NumberFieldScrubAreaCursor,
  NumberFieldGroup,
  NumberFieldDecrement,
  NumberFieldInput,
  NumberFieldIncrement,
} from "./number-field";

import { tv } from "tailwind-variants";

const numberField = tv({
  slots: {
    root: "flex flex-col items-start gap-1.5",
    scrubArea: [
      "w-full cursor-ew-resize select-none",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "[&>label]:cursor-ew-resize",
    ],
    scrubAreaCursor: "",
    group: [
      "group flex h-8 items-center rounded-md border border-input bg-background shadow-sm transition-all duration-150 ease-default",
      "focus-within:ring-2 focus-within:ring-ring/50",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "data-invalid:border-destructive/50",
      "focus-within:data-invalid:ring-destructive/50",
      "dark:bg-input/15",
    ],
    decrement: [
      "flex h-full w-8 items-center justify-center rounded-s-[inherit] bg-input/20 text-foreground transition-colors duration-150 ease-default select-none",
      "hover:bg-accent hover:text-accent-foreground",
      "[&>svg]:size-4",
    ],
    input: [
      "h-full items-center rounded-[inherit] text-center text-sm text-foreground tabular-nums outline-none",
      "group-has-data-[slot='number-field-decrement']:rounded-s-none",
      "group-has-data-[slot='number-field-increment']:rounded-e-none",
      "placeholder:text-muted-foreground",
    ],
    increment: [
      "flex h-full w-8 items-center justify-center rounded-e-[inherit] bg-input/20 text-foreground transition-colors duration-150 ease-default select-none",
      "hover:bg-accent hover:text-accent-foreground",
      "[&>svg]:size-4",
    ],
  },
});

export { numberField };

"use client";

import { useDirection } from "@base-ui/react";
import { NumberField as BaseNumberField } from "@base-ui/react/number-field";
import { MinusIcon, MoveHorizontalIcon, PlusIcon } from "lucide-react";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { numberField } from "./number-field.style";

function NumberField({ className, ...props }: BaseNumberField.Root.Props) {
  const direction = useDirection();

  return (
    <BaseNumberField.Root
      data-slot="number-field"
      className={mergeSlotClassName(numberField().root, className)}
      {...props}
      dir={direction}
    />
  );
}

function NumberFieldScrubArea({
  className,
  ...props
}: BaseNumberField.ScrubArea.Props) {
  return (
    <BaseNumberField.ScrubArea
      data-slot="number-field-scrub-area"
      className={mergeSlotClassName(numberField().scrubArea, className)}
      {...props}
    />
  );
}

function NumberFieldScrubAreaCursor({
  className,
  children,
  ...props
}: BaseNumberField.ScrubAreaCursor.Props) {
  return (
    <BaseNumberField.ScrubAreaCursor
      data-slot="number-field-scrub-area-cursor"
      className={mergeSlotClassName(numberField().scrubAreaCursor, className)}
      {...props}
    >
      {children ?? <MoveHorizontalIcon />}
    </BaseNumberField.ScrubAreaCursor>
  );
}

function NumberFieldGroup({
  className,
  ...props
}: BaseNumberField.Group.Props) {
  return (
    <BaseNumberField.Group
      data-slot="number-field-group"
      className={mergeSlotClassName(numberField().group, className)}
      {...props}
    />
  );
}

function NumberFieldDecrement({
  className,
  children,
  ...props
}: BaseNumberField.Decrement.Props) {
  return (
    <BaseNumberField.Decrement
      data-slot="number-field-decrement"
      className={mergeSlotClassName(numberField().decrement, className)}
      {...props}
    >
      {children ?? <MinusIcon />}
    </BaseNumberField.Decrement>
  );
}

function NumberFieldInput({
  className,
  ...props
}: BaseNumberField.Input.Props) {
  return (
    <BaseNumberField.Input
      data-slot="number-field-input"
      className={mergeSlotClassName(numberField().input, className)}
      {...props}
    />
  );
}

function NumberFieldIncrement({
  className,
  children,
  ...props
}: BaseNumberField.Increment.Props) {
  return (
    <BaseNumberField.Increment
      data-slot="number-field-increment"
      className={mergeSlotClassName(numberField().increment, className)}
      {...props}
    >
      {children ?? <PlusIcon />}
    </BaseNumberField.Increment>
  );
}

export {
  NumberField,
  NumberFieldScrubArea,
  NumberFieldScrubAreaCursor,
  NumberFieldGroup,
  NumberFieldDecrement,
  NumberFieldInput,
  NumberFieldIncrement,
};
